import { HttpErrorResponse } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { NgForm } from '@angular/forms';
import { Router } from '@angular/router';
import { leishmania_species } from '../../model/leishmania_species';
import { LeishmaniaSpeciesService } from '../../services/leishmania-species.service';

@Component({
  selector: 'app-leishmania-species',
  templateUrl: './leishmania-species.component.html',
  styleUrls: ['./leishmania-species.component.scss']
})
export class LeishmaniaSpeciesComponent implements OnInit {

  constructor(private LeishmaniaSpeciesService: LeishmaniaSpeciesService, private router: Router) { }

  ngOnInit(): void {
    this.get_leishmania_species();
  }

  speciess: leishmania_species[];
  content_speciess: boolean;
  get_leishmania_species() {
    this.LeishmaniaSpeciesService.get_all_species().subscribe(
      data => {
        if (data.status == 200) {
          this.speciess = data.body
          this.content_speciess = true;
        }
        else if (data.status == 204) {
          this.content_speciess = false;
        }
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.LeishmaniaSpeciesService.clear();
          this.router.navigateByUrl('/login');
        }
      }
    )
  }

  species_update: leishmania_species;
  new_value = "";
  public update(species: leishmania_species) {
    if (window.confirm('Are you sure')) {
      this.new_value = (<HTMLInputElement>document.getElementById("species_update_information")).value;
      species.information = this.new_value;
      this.LeishmaniaSpeciesService.update_species(species).subscribe(
        (response: string) => {
          this.get_leishmania_species();
          this.alert('Leishmania species successfully updated', 'warning');

        },
        (error: HttpErrorResponse) => {
          if (error) {
            console.log(error.message); console.log(error.status)
          }
        }
      )
    }
  }

  public set(species: leishmania_species) {
    this.species_update = species;
    (<HTMLInputElement>document.getElementById("species_update_information")).value = species.information;

  }


  hide() {
    let element: HTMLElement = document.getElementById('r') as HTMLElement;
    element.click();
  }

  cancel_add(species: NgForm) {
    species.resetForm();
    this.existe=false;
  }

  public delete(species: string) {
    if (window.confirm('Are you sure')) {
      this.LeishmaniaSpeciesService.delete_species(species).subscribe(
        (response: string) => {
          this.get_leishmania_species();
          this.alert('Leishmania species successfully deleted', 'danger');

        },
        (error: HttpErrorResponse) => {
          if (error) {
            console.log(error.message); console.log(error.status)
          }
        }
      )
    }
  }

  existe: boolean;
  public add(leishmania_species: NgForm) {
    console.log(leishmania_species.value);
    this.LeishmaniaSpeciesService.add_species(leishmania_species.value).subscribe(
      (response: string) => {
        if (response== "201") {
          this.existe=false;
          this.get_leishmania_species();
          this.alert('Leishmania species successfully added', 'primary');
          leishmania_species.resetForm();
          this.hide()
        }
        else if 
        (response == "200")
        { this.existe=true;}
      
      },
      (error: HttpErrorResponse) => {
        if (error) {
          console.log(error.message); console.log(error.status)
        }
      }
    )
  }


  alertsDismiss: any = [];
  alert(msg: string, type: string) {
    this.alertsDismiss.push({
      type: type,
      msg: msg,
      timeout: 2500
    });
  }


}
